// Compares incoming and output state and decides pass/fail.
const cfg = $('Configuration').first().json;
const before = $('Record Incoming State').first().json;
const out = [];
for (const item of $input.all()) {
  const after = item.json;
  const reasons = [];
  const claim = String(after.pdfx_claim ?? '');
  if (!claim || /none|false/i.test(claim)) reasons.push('Output does not carry a PDF/X claim');
  if (after.uses_nonembedded_fonts === true || String(after.uses_nonembedded_fonts) === 'true') reasons.push('Output still uses non-embedded fonts');
  if (String(cfg.pdfXVersion) === 'PDF/X-1a' && (after.contains_transparency === true || String(after.contains_transparency) === 'true')) reasons.push('PDF/X-1a output still contains transparency');
  if (Number(after.page_count) !== Number(before.incoming.page_count)) reasons.push(`Page count changed: ${before.incoming.page_count} -> ${after.page_count}`);
  const report = {
    file: before.fileName,
    processedAt: new Date().toISOString(),
    pass: reasons.length === 0,
    reasons,
    target: { colorProfile: cfg.colorProfile, pdfXVersion: cfg.pdfXVersion },
    incoming: before.incoming,
    output: { pdfx_claim: after.pdfx_claim, uses_nonembedded_fonts: after.uses_nonembedded_fonts, contains_transparency: after.contains_transparency, page_count: after.page_count, pdf_version: after.pdf_version },
  };
  const base = String(before.fileName ?? 'file.pdf').replace(/\.pdf$/i, '');
  out.push({ json: { report, outputFileName: `${base}_${String(cfg.pdfXVersion).replace('/', '')}.pdf`, reportFileName: `${base}_preflight.json`, reportText: JSON.stringify(report, null, 2) }, binary: item.binary });
}
return out;

